    color: white;
    padding: 10px 20px;
    border: 1.5px solid #102310;
    font-size: 16px;
    border-radius: 50px;
    cursor: pointer;
    position: relative;
    overflow: hidden;
    transition: color 0.5s ease;
    background-color: transparent;
    z-index: 1;
}

.fancy-button-header::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%; 
    width: 100%;
    color: white;
    height: 100%;
    background-color: #0f440f;
    transition: left 0.5s ease;
    z-index: -1;
    border-radius: 50px;
}

.fancy-button-header:hover::before {
    left: 0;
}

.fancy-button-header:hover {
    color: white;
