en":[{"id":27,"name":"ct_headline","options":{"ct_id":27,"ct_parent":16,"selector":"headline-27-200","original":{"tag":"h2","font-family":["global","Text"],"font-weight":"600","-webkit-font-smoothing":"antialiased","font-size":"28"},"nicename":"Heading (#27)","ct_content":"Every Volunteer Leaves an Impact","activeselector":false,"media":{"phone-portrait":{"original":{"font-size":"18"}}}},"depth":5},{"id":28,"name":"ct_text_block","options":{"ct_id":28,"ct_parent":16,"selector":"text_block-28-200","original":{"font-size":"18","color":"color(7)","-webkit-font-smoothing":"antialiased"},"nicename":"Text (#28)","ct_content":"Volunteer in Tanzania with AVE on a wide range of projects including Teaching, Medical, Childcare, HIV/AIDS Support, Photography and Animal Welfare. For an insight on what the occupation of a Safari Guide is, we also offer an internship taught by our guides with a combined 20 years experience. Volunteers are based in Arusha with volunteer projects located in local rural and urban communities.&nbsp;","activeselector":false,"media":{"phone-portrait":{"original":{"font-size":"14"}}}},"depth":5},{"id":39,"name":"ct_headline","options":{"ct_id":39,"ct_parent":16,"selector":"headline-39-200","original":{"tag":"h2","font-family":["global","Text"],"font-weight":"600","-webkit-font-smoothing":"antialiased","font-size":"28","color":"color(11)"},"nicename":"Heading (#39)","ct_content":"Most affordable fees","activeselector":false,"media":{"phone-portrait":{"original":{"font-size":"18"}}}},"depth":5},{"id":41,"name":"ct_text_block","options":{"ct_id":41,"ct_parent":16,"selector":"text_block-41-200","original":{"font-size":"18","color":"color(7)","-webkit-font-smoothing":"antialiased"},"nicename":"Text (#41)","ct_content":"At Arusha Volunteer Experience, we pride ourselves with our low program costs. We are able to accommodate volunteers while supporting local schools and businesses, with your help! You will not find a more affordable and trustworthy volunteer organization in Tanzania!&nbsp;","activeselector":false,"media":{"phone-portrait":{"original":{"font-size":"14"}}}},"depth":5},{"id":43,"name":"ct_headline","options":{"ct_id":43,"ct_parent":16,"selector":"headline-43-200","original":{"tag":"h2","font-family":["global","Text"],"font-weight":"600","-webkit-font-smoothing":"antialiased","font-size":"28","color":"color(6)"},"nicename":"Heading (#43)","ct_content":"Superior Support","activeselector":false,"media":{"phone-portrait":{"original":{"font-size":"18"}}}},"depth":5},{"id":45,"name":"ct_text_block","options":{"ct_id":45,"ct_parent":16,"selector":"text_block-45-200","original":{"font-size":"18","color":"color(7)","-webkit-font-smoothing":"antialiased"},"nicename":"Text (#45)","ct_content":"<div>Your experience with AVE will be very comfortable and rewarding. Joining our local team in Tanzania will ensure you feel supported every step of the way – from planning to arrival, orientation and days in your placement!</div><div>Contact Michael, Natalie, or Fox for any questions you may have. However, you will be designated a manager once enrollment is complete!</div>","activeselector":false,"media":{"phone-portrait":{"original":{"font-size":"14"}}}},"depth":5}]},{"id":17,"name":"ct_div_block","options":{"ct_id":17,"ct_parent":15,"selector":"div_block-17-200","original":{"width-unit":"%","width":"55","text-align":"left","align-items":"center","justify-content":"center","gap":"40"},"nicename":"Right","activeselector":false,"media":{"phone-portrait":{"original":{"width":"100"}}}},"depth":4,"children":[{"id":18,"name":"ct_div_block","options":{"ct_id":18,"ct_parent":17,"selector":"div_block-18-200","original":{"flex-direction":"row","display":"flex","align-items":"center","width-unit":"%","width":"100","justify-content":"space-between"},"nicename":"Image Flow One","activeselector":false},"depth":5,"children":[{"id":21,"name":"ct_div_block","options":{"ct_id":21,"ct_parent":18,"selector":"div_block-21-200","original":{"backgro