iginal":{"code-php":"<!-- -->","code-js":"","code-css":"body:not(.ng-scope) :is(.oxel_logo_slider, #incspec) {
	flex-direction: row;
	align-items: center;
	overflow: hidden;
	position: relative;
	height: 100px;

	--animationspeed: 30s;
	--animationdelay: calc( var(--animationspeed) / 2 );
}

body:not(.ng-scope) .oxel_logo_slider__image_carrier {
	flex-shrink: 0;
	position: absolute;
	animation-name: slidelogo;
	animation-duration: var(--animationspeed);
	animation-timing-function: linear;
	animation-iteration-count: infinite;
}

body:not(.ng-scope) .oxel_logo_slider__image_carrier--delay {
	transform: translateX(100%);
	animation-name: slidelogo;
	animation-delay: calc(var(--animationdelay) * -1);
}

.oxel_logo_slider:hover .oxel_logo_slider__image_carrier {
	animation-play-state: paused;
}

@keyframes slidelogo {
	from {
		transform: translateX(100%);
	}
	to {
		transform: translateX(-100%);
	}
}
