00","original":{"tag":"h2","font-family":["global","Text"],"-webkit-font-smoothing":"antialiased","font-weight":"600","letter-spacing":"1","font-size":"24","color":"color(11)"},"nicename":"Heading (#87)","ct_content":"Photography","activeselector":false},"depth":6}],"depth":5}],"depth":4}],"depth":3}]}]},{"id":93,"name":"ct_section","options":{"ct_id":93,"ct_parent":0,"selector":"section-93-200","original":{"section-width":"full-width","align-items":"center","height":"200","display":"none","justify-content":"center"},"nicename":"Activities","activeselector":false},"depth":1,"children":[{"id":94,"name":"ct_div_block","options":{"ct_id":94,"ct_parent":93,"selector":"div_block-94-200","original":{"width":"100","width-unit":"%","max-width":"1400","padding-top":"0"},"nicename":"Wrapper","activeselector":false},"depth":2,"children":[{"id":95,"name":"ct_div_block","options":{"ct_id":95,"ct_parent":94,"selector":"div_block-95-200","classes":["oxel_logo_slider"],"activeselector":"oxel_logo_slider","nicename":"Logo Slider"},"children":[{"id":96,"name":"ct_code_block","options":{"ct_id":96,"ct_parent":95,"selector":"code_block-96-200","original":{"code-php":"<!-- -->","code-js":"","code-css":"body:not(.ng-scope) :is(.oxel_logo_slider, #incspec) {
	flex-direction: row;
	align-items: center;
	overflow: hidden;
	position: relative;
	height: 100px;

	--animationspeed: 30s;
	--animationdelay: calc( var(--animationspeed) / 2 );
}

body:not(.ng-scope) .oxel_logo_slider__image_carrier {
	flex-shrink: 0;
	position: absolute;
	animation-name: slidelogo;
	animation-duration: var(--animationspeed);
	animation-timing-function: linear;
	animation-iteration-count: infinite;
}

body:not(.ng-scope) .oxel_logo_slider__image_carrier--delay {
	transform: translateX(100%);
	animation-name: slidelogo;
	animation-delay: calc(var(--animationdelay) * -1);
}

.oxel_logo_slider:hover .oxel_logo_slider__image_carrier {
	animation-play-state: paused;
}

@keyframes slidelogo {
	from {
		transform: translateX(100%);
	}
	to {
		transform: translateX(-100%);
	}
}
