ct_id":53,"ct_parent":52,"selector":"code_block-53-200","original":{"code-php":"<!-- -->","code-js":"","code-css":"body:not(.ng-scope) :is(.oxel_logo_slider, #incspec) {
	flex-direction: row;
	align-items: center;
	overflow: hidden;
	position: relative;
	height: 100px;

	--animationspeed: 30s;
	--animationdelay: calc( var(--animationspeed) / 2 );
}

body:not(.ng-scope) .oxel_logo_slider__image_carrier {
	flex-shrink: 0;
	position: absolute;
	animation-name: slidelogo;
	animation-duration: var(--animationspeed);
	animation-timing-function: linear;
	animation-iteration-count: infinite;
}

body:not(.ng-scope) .oxel_logo_slider__image_carrier--delay {
	transform: translateX(100%);
	animation-name: slidelogo;
	animation-delay: calc(var(--animationdelay) * -1);
}

.oxel_logo_slider:hover .oxel_logo_slider__image_carrier {
	animation-play-state: paused;
}

@keyframes slidelogo {
	from {
		transform: translateX(100%);
	}
	to {
		transform: translateX(-100%);
	}
}
"},"nicename":"Logo Slider Code","ct_content":""},"depth":4},{"id":54,"name":"ct_div_block","options":{"ct_id":54,"ct_parent":52,"selector":"div_block-54-200","classes":["oxel_logo_slider__image_carrier"],"nicename":"Logo Slide","original":{"custom-attributes":[{"name":"position","value":"0"}]}},"children":[{"id":55,"name":"ct_div_block","options":{"ct_id":55,"ct_parent":54,"selector":"div_block-55-200","classes":["oxel_logo_slider__logo"],"nicename":"Logo Div","activeselector":""},"children":[{"id":77,"name":"ct_headline","options":{"ct_id":77,"ct_parent":55,"selector":"headline-77-200","original":{"tag":"h2","font-family":["global","Text"],"-webkit-font-smoothing":"antialiased","font-weight":"600","letter-spacing":"1","font-size":"24","color":"color(6)"},"nicename":"Heading (#77)","ct_content":"Childcare","activeselector":false},"depth":6}],"depth":5},{"id":57,"name":"ct_div_block","options":{"ct_id":57,"ct_parent":54,"selector":"div_block-57-200","classes":["oxel_logo_slider__logo"],"nicename":"Logo Div","activeselector":false},"children":[{"id":78,"name":"ct_headline","options":{"ct_id":78,"ct_parent":57,"selector":"headline-78-200","original":{"tag":"h2","font-family":["global","Text"],"-webkit-font-smoothing":"antialiased","font-weight":"600","letter-spacing":"1","font-size":"24","color":"color(11)"},"nicename":"Heading (#78)","ct_content":"Teaching","activeselector":false},"depth":6}],"depth":5},{"id":59,"name":"ct_div_block","options":{"ct_id":59,"ct_parent":54,"selector":"div_block-59-200","classes":["oxel_logo_slider__logo"],"nicename":"Logo Div","activeselector":false},"children":[{"id":80,"name":"ct_headline","options":{"ct_id":80,"ct_parent":59,"selector":"headline-80-200","original":{"tag":"h2","font-family":["global","Text"],"-webkit-font-smoothing":"antialiased","font-weight":"600","letter-spacing":"1","font-size":"24","color":"color(6)"},"nicename":"Heading (#80)","ct_content":"Medical","activeselector":false},"depth":6}],"depth":5},{"id":61,"name":