x","text-align":"left","width-unit":"%","width":"50","gap":"10"},"nicename":"Left","media":{"phone-portrait":{"original":{"width":"100"}}}},"depth":4,"children":[{"id":27,"name":"ct_headline","options":{"ct_id":27,"ct_parent":16,"selector":"headline-27-200","original":{"tag":"h2","font-family":["global","Text"],"font-weight":"600","-webkit-font-smoothing":"antialiased","font-size":"28"},"nicename":"Heading (#27)","ct_content":"Every Volunteer Leaves an Impact","activeselector":"user-dp","media":{"phone-portrait":{"original":{"font-size":"18"}}}},"depth":5},{"id":28,"name":"ct_text_block","options":{"ct_id":28,"ct_parent":16,"selector":"text_block-28-200","original":{"font-size":"18","color":"color(7)","-webkit-font-smoothing":"antialiased"},"nicename":"Text (#28)","ct_content":"Volunteer in Tanzania with AVE on a wide range of projects including Teaching, Medical, Childcare, HIV/AIDS Support, Photography and Animal Welfare. For an insight on what the occupation of a Safari Guide is, we also offer an internship taught by our guides with a combined 20 years experience. Volunteers are based in Arusha with volunteer projects located in local rural and urban communities.&nbsp;","activeselector":"team-card-content","media":{"phone-portrait":{"original":{"font-size":"14"}}}},"depth":5},{"id":39,"name":"ct_headline","options":{"ct_id":39,"ct_parent":16,"selector":"headline-39-200","original":{"tag":"h2","font-family":["global","Text"],"font-weight":"600","-webkit-font-smoothing":"antialiased","font-size":"28","color":"color(11)"},"nicename":"Heading (#39)","ct_content":"Most affordable fees","activeselector":false,"media":{"phone-portrait":{"original":{"font-size":"18"}}}},"depth":5},{"id":41,"name":"ct_text_block","options":{"ct_id":41,"ct_parent":16,"selector":"text_block-41-200","original":{"font-size":"18","color":"color(7)","-webkit-font-smoothing":"antialiased"},"nicename":"Text (#41)","ct_content":"At Arusha Volunteer Experience, we pride ourselves with our low progr