ontent":"<span id="ct-placeholder-699"></span>&nbsp;&amp; Tours","activeselector":false,"media":{"phone-portrait":{"original":{"font-size":"17"}}}},"depth":5,"children":[{"id":699,"name":"ct_span","options":{"ct_id":699,"ct_parent":67,"selector":"span-699-517","original":{"color":"color(6)"},"nicename":"Span (#699)","ct_content":"Destinations "},"depth":6}]}]},{"id":1722,"name":"ct_div_block","options":{"original":[],"classes":["questions"],"ct_id":1722,"ct_parent":63,"nicename":"Div (#1722)","selector":"div_block-1722-517","activeselector":"questions"},"depth":4,"children":[{"id":1869,"name":"ct_div_block","options":{"original":{"width-unit":"%","background-color":"color(1)","border-radius":"30","text-align":"left","align-items":"center","padding-top":"8","padding-right":"20","padding-bottom":"8","padding-left":"20"},"classes":[],"ct_id":1869,"ct_parent":1722,"nicename":"Div (#1869)","selector":"div_block-1869-517","activeselector":false},"depth":5,"children":[{"id":1870,"name":"ct_text_block","options":{"ct_id":1870,"ct_parent":1869,"selector":"text_block-1870-517","original":{"font-size":"20","color":"color(3)"},"nicename":"Text (#29)","ct_content":"3 questions","activeselector":false,"media":{"phone-portrait":{"original":{"font-size":"10"}}}},"depth":6}]}]}]},{"id":71,"name":"ct_div_block","options":{"ct_id":71,"ct_parent":62,"selector":"div_block-71-517","original":{"width":"100","width-unit":"%"},"nicename":"accordion","activeselector":false},"depth":3,"children":[{"id":72,"name":"ct_div_block","options":{"ct_id":72,"ct_parent":71,"selector":"div_block-72-517","classes":["oxel_accordion"],"nicename":"Accordion","activeselector":"oxel_accordion"},"children":[{"id":73,"name":"ct_code_block","options":{"ct_id":73,"ct_parent":72,"selector":"code_block-73-517","original":{"code-php":"<!-- -->","code-js":"//** Oxygen Composite Elements Settings Section **//
//** Edit the variables below to change the behavior of the element. **//

var closeOtherToggles = true; // Set this to true to close all other accordions when an accordion is expanded.

//** That's it, stop editing! **/
var ready = (callback) => {
  if (document.readyState != "loading") callback();
  else document.addEventListener("DOMContentLoaded", callback);
}

ready(() => { 
	// Expand the content when row is clicked.
	document.querySelectorAll('.oxel_accordion__row').forEach( accordion => {
		accordion.addEventListener('click', function(e) {
			accordion.classList.toggle('oxel_accordion__row--active');
			accordion.nextElementSibling.classList.toggle('oxel_accordion__content__hidden');

			switch( accordion.getAttribute('aria-expanded') ) {
				case 'true':
					accordion.setAttribute('aria-expanded', 'false');
				break;
				case 'false':
					accordion.setAttribute('aria-expanded', 'true');
				break;
			}

			if( closeOtherToggles == true ) {
				accordion.parentElement.querySelectorAll('.oxel_accordion__row--active').forEach( row => {
					if( row != accordion ) { 
						row.classList.remove('oxel_accordion__row--active');
						row.setAttribute('aria-expanded', 'false');
						row.nextElementSibling.classList.add('oxel_accordion__content__hidden');
					}
				});
			}
		})
	})

});

