ent":"Destinations "},"depth":6}]}]},{"id":1708,"name":"ct_div_block","options":{"original":{"width-unit":"%","background-color":"color(1)","border-radius":"30","text-align":"left","align-items":"center","padding-top":"8","padding-right":"20","padding-bottom":"8","padding-left":"20"},"classes":[],"ct_id":1708,"ct_parent":63,"nicename":"Div (#1708)","selector":"div_block-1708-517","activeselector":false},"depth":4,"children":[{"id":1709,"name":"ct_text_block","options":{"ct_id":1709,"ct_parent":1708,"selector":"text_block-1709-517","original":{"font-size":"20","color":"color(3)"},"nicename":"Text (#29)","ct_content":"3 questions"},"depth":5}]}]},{"id":71,"name":"ct_div_block","options":{"ct_id":71,"ct_parent":62,"selector":"div_block-71-517","original":{"width":"100","width-unit":"%"},"nicename":"accordion","activeselector":false},"depth":3,"children":[{"id":72,"name":"ct_div_block","options":{"ct_id":72,"ct_parent":71,"selector":"div_block-72-517","classes":["oxel_accordion"],"nicename":"Accordion","activeselector":"oxel_accordion"},"children":[{"id":73,"name":"ct_code_block","options":{"ct_id":73,"ct_parent":72,"selector":"code_block-73-517","original":{"code-php":"<!-- -->","code-js":"//** Oxygen Composite Elements Settings Section **//
//** Edit the variables below to change the behavior of the element. **//

var closeOtherToggles = true; // Set this to true to close all other accordions when an accordion is expanded.

//** That's it, stop editing! **/
var ready = (callback) => {
  if (document.readyState != "loading") callback();
  else document.addEventListener("DOMContentLoaded", callback);
}

ready(() => { 
	// Expand the content when row is clicked.
	document.querySelectorAll('.oxel_accordion__row').forEach( accordion => {
		accordion.addEventListener('click', function(e) {
			accordion.classList.toggle('oxel_accordion__row--active');
			accordion.nextElementSibling.classList.toggle('oxel_accordion__content__hidden');

			switch( accordion.getAttribute('aria-expanded') ) {
				case 'true':
					accordion.setAttribute('aria-expanded', 'false');
				break;
				case 'false':
					accordion.setAttribute('aria-expanded', 'true');
				break;
			}

			if( closeOtherToggles == true ) {
				accordion.parentElement.querySelectorAll('.oxel_accordion__row--active').forEach( row => {
					if( row != accordion ) { 
						row.classList.remove('oxel_accordion__row--active');
						row.setAttribute('aria-expanded', 'false');
						row.nextElementSibling.classList.add('oxel_accordion__content__hidden');
					}
				});
			}
		})
	})

});

