{"ct_id":19,"ct_parent":16,"selector":"div_block-19-517","original":[],"nicename":"Div (#19)","activeselector":"questions","classes":["questions"]},"depth":4,"children":[{"id":28,"name":"ct_div_block","options":{"ct_id":28,"ct_parent":19,"selector":"div_block-28-517","original":{"width-unit":"%","background-color":"color(1)","border-radius":"30","text-align":"left","align-items":"center","padding-top":"8","padding-right":"20","padding-bottom":"8","padding-left":"20"},"nicename":"Div (#28)","activeselector":false},"depth":5,"children":[{"id":29,"name":"ct_text_block","options":{"ct_id":29,"ct_parent":28,"selector":"text_block-29-517","original":{"font-size":"20","color":"color(2)"},"nicename":"Text (#29)","ct_content":"3 questions","activeselector":false},"depth":6}]}]}]},{"id":30,"name":"ct_div_block","options":{"ct_id":30,"ct_parent":15,"selector":"div_block-30-517","original":{"width":"100","width-unit":"%","height":"70","height-unit":"%"},"nicename":"accordion","activeselector":false},"depth":3,"children":[{"id":31,"name":"ct_div_block","options":{"ct_id":31,"ct_parent":30,"selector":"div_block-31-517","classes":["oxel_accordion"],"nicename":"Accordion","activeselector":"oxel_accordion"},"children":[{"id":32,"name":"ct_code_block","options":{"ct_id":32,"ct_parent":31,"selector":"code_block-32-517","original":{"code-php":"<!-- -->","code-js":"//** Oxygen Composite Elements Settings Section **//
//** Edit the variables below to change the behavior of the element. **//

var closeOtherToggles = true; // Set this to true to close all other accordions when an accordion is expanded.

//** That's it, stop editing! **/
var ready = (callback) => {
  if (document.readyState != "loading") callback();
  else document.addEventListener("DOMContentLoaded", callback);
}

ready(() => { 
	// Expand the content when row is clicked.
	document.querySelectorAll('.oxel_accordion__row').forEach( accordion => {
		accordion.addEventListener('click', function(e) {
			accordion.classList.toggle('oxel_accordion__row--active');
			accordion.nextElementSibling.classList.toggle('oxel_accordion__content__hidden');

			switch( accordion.getAttribute('aria-expanded') ) {
				case 'true':
					accordion.setAttribute('aria-expanded', 'false');
				break;
				case 'false':
					accordion.setAttribute('aria-expanded', 'true');
				break;
			}

			if( closeOtherToggles == true ) {
				accordion.parentElement.querySelectorAll('.oxel_accordion__row--active').forEach( row => {
					if( row != accordion ) { 
						row.classList.remove('oxel_accordion__row--active');
						row.setAttribute('aria-expanded', 'false');
						row.nextElementSibling.classList.add('oxel_accordion__content__hidden');
					}
				});
			}
		})
	})

});

","code-css":"body.ng-scope .oxel_accordion__content__hidden {
	max-height: 10000px;
	opacity: 1;
	margin-top: 0px;
	z-index: 1;
}

.oxel_accordion__row--active > .oxel_accordion__icon {
	transform: rotate(180deg);
}"},"nicename":"Accordion Code","activeselector":false,"ct_content":""},"depth":5},{"id":33,"name":"ct_div_block","options":{"ct_id":33,"ct_parent":31,"selector":"div_block-33-517","classes":["oxel_accordion__row"],"nicename":"Accordion Row","activeselector":"oxel_accordion__row","original":{"useCustomTag":"true","tag":"button","custom-attributes":[{"name":"aria-expanded","value":"false"}]}},"children":[{"id":34,"name":"ct_div_block","options":{"ct_id":34,"ct_parent":33,"selector":"div_block-34-517","classes":["oxel_accordion__row_left"],"activeselector":"oxel_accordion__row_left","nicename":"Div (#34)"},"children":[{"id":36,"name":"ct_text_block","options":{"ct_id":36,"ct_parent":34,"selector":"text_block-36-517","classes":["oxel_accordion__row__label"],"activeselector":"oxel_accordion__row__label","ct_content":"How do you book&nbsp; a tour or vacation package?","nicename":"Text (#36)","original":[]},"depth":7}],"depth":6},{"id":574,"name":"ct_fancy_icon","options":{"ct_id":574,"ct_parent":33,"selector":"fancy_icon-574-517","original":{"icon-id":"Lineariconsicon-chevron-down"},"classes":["oxel_accordion__icon"],"ct_content":"","nicename":"Icon (#574)"},"depth":6}],"depth":5},{"id":38,"name":"ct_div_block","options":{"ct_id":38,"ct_parent":31,"selector":"div_block-38-517","classes":["oxel_accordion__content","oxel_accordion__content__hidden"],"nicename":"Accordion Content","activeselector":false,"original":{"conditionspreview":"2","globalConditionsResult":true}},"children":[{"id":39,"name":"ct_div_block","options":{"ct_id":39,"ct_parent":38,"selector":"div_block-39-517","original":{"flex-direction":"row","display":"flex","flex-wrap":"wrap"},"nicename":"Div (#39)"},"children":[{"id":40,"name":"ct_text_block","options":{"ct_id":40,"ct_parent":39,"selector":"text_block-40-517","ct_content":"You can book directly through our website by selecting your desired destination, dates, and package. Our booking system will guide you through the process step by step. You can also