icename":"Span (#712)","ct_content":"Customer&nbsp;"},"depth":6}]}]},{"id":157,"name":"ct_div_block","options":{"original":[],"classes":["questions"],"ct_id":157,"ct_parent":152,"nicename":"Div (#19)","selector":"div_block-157-517","activeselector":"questions"},"depth":4,"children":[{"id":158,"name":"ct_div_block","options":{"original":{"width-unit":"%","background-color":"color(1)","border-radius":"30","text-align":"left","align-items":"center","padding-top":"8","padding-right":"20","padding-bottom":"8","padding-left":"20"},"classes":[],"ct_id":158,"ct_parent":157,"nicename":"Div (#28)","selector":"div_block-158-517","activeselector":false},"depth":5,"children":[{"id":159,"name":"ct_text_block","options":{"ct_id":159,"ct_parent":158,"selector":"text_block-159-517","original":{"font-size":"20","color":"color(3)"},"nicename":"Text (#29)","ct_content":"3 questions","activeselector":false},"depth":6}]}]}]},{"id":160,"name":"ct_div_block","options":{"ct_id":160,"ct_parent":151,"selector":"div_block-160-517","original":{"width":"100","width-unit":"%","height":"70","height-unit":"%"},"nicename":"accordion","activeselector":false},"depth":3,"children":[{"id":161,"name":"ct_div_block","options":{"ct_id":161,"ct_parent":160,"selector":"div_block-161-517","classes":["oxel_accordion"],"nicename":"Accordion","activeselector":false},"children":[{"id":162,"name":"ct_code_block","options":{"ct_id":162,"ct_parent":161,"selector":"code_block-162-517","original":{"code-php":"<!-- -->","code-js":"//** Oxygen Composite Elements Settings Section **//
//** Edit the variables below to change the behavior of the element. **//

var closeOtherToggles = true; // Set this to true to close all other accordions when an accordion is expanded.

//** That's it, stop editing! **/
var ready = (callback) => {
  if (document.readyState != "loading") callback();
  else document.addEventListener("DOMContentLoaded", callback);
}

ready(() => { 
	// Expand the content when row is clicked.
	document.querySelectorAll('.oxel_accordion__row').forEach( accordion => {
		accordion.addEventListener('click', function(e) {
			accordion.classList.toggle('oxel_accordion__row--active');
			accordion.nextElementSibling.classList.toggle('oxel_accordion__content__hidden');

			switch( accordion.getAttribute('aria-expanded') ) {
				case 'true':
					accordion.setAttribute('aria-expanded', 'false');
				break;
				case 'false':
					accordion.setAttribute('aria-expanded', 'true');
				break;
			}

			if( closeOtherToggles == true ) {
				accordion.parentElement.querySelectorAll('.oxel_accordion__row--active').forEach( row => {
					if( row != accordion ) { 
						row.classList.remove('oxel_accordion__row--active');
						row.setAttribute('aria-expanded', 'false');
						row.nextElementSibling.classList.add('oxel_accordion__content__hidden');
					}
				});
			}
		})
	})

});

