an-570-517","original":{"color":"color(6)"},"nicename":"Span (#570)","ct_content":"Booking &amp;"},"depth":6}]}]},{"id":19,"name":"ct_div_block","options":{"ct_id":19,"ct_parent":16,"selector":"div_block-19-517","original":[],"nicename":"Div (#19)","activeselector":"questions","classes":["questions"]},"depth":4,"children":[{"id":28,"name":"ct_div_block","options":{"ct_id":28,"ct_parent":19,"selector":"div_block-28-517","original":{"width-unit":"%","background-color":"color(1)","border-radius":"30","text-align":"left","align-items":"center","padding-top":"8","padding-right":"20","padding-bottom":"8","padding-left":"20"},"nicename":"Div (#28)","activeselector":false},"depth":5,"children":[{"id":29,"name":"ct_text_block","options":{"ct_id":29,"ct_parent":28,"selector":"text_block-29-517","original":{"font-size":"20","color":"color(2)"},"nicename":"Text (#29)","ct_content":"3 questions","activeselector":false,"media":{"phone-portrait":{"original":{"font-size":"10","font-family":["global","Text"],"font-weight":"700"}}}},"depth":6}]}]}]},{"id":30,"name":"ct_div_block","options":{"ct_id":30,"ct_parent":15,"selector":"div_block-30-517","original":{"width":"100","width-unit":"%","height":"70","height-unit":"%"},"nicename":"accordion","activeselector":false},"depth":3,"children":[{"id":31,"name":"ct_div_block","options":{"ct_id":31,"ct_parent":30,"selector":"div_block-31-517","classes":["oxel_accordion"],"nicename":"Accordion","activeselector":"oxel_accordion"},"children":[{"id":32,"name":"ct_code_block","options":{"ct_id":32,"ct_parent":31,"selector":"code_block-32-517","original":{"code-php":"<!-- -->","code-js":"//** Oxygen Composite Elements Settings Section **//
//** Edit the variables below to change the behavior of the element. **//

var closeOtherToggles = true; // Set this to true to close all other accordions when an accordion is expanded.

//** That's it, stop editing! **/
var ready = (callback) => {
  if (document.readyState != "loading") callback();
  else document.addEventListener("DOMContentLoaded", callback);
}

ready(() => { 
	// Expand the content when row is clicked.
	document.querySelectorAll('.oxel_accordion__row').forEach( accordion => {
		accordion.addEventListener('click', function(e) {
			accordion.classList.toggle('oxel_accordion__row--active');
			accordion.nextElementSibling.classList.toggle('oxel_accordion__content__hidden');

			switch( accordion.getAttribute('aria-expanded') ) {
				case 'true':
					accordion.setAttribute('aria-expanded', 'false');
				break;
				case 'false':
					accordion.setAttribute('aria-expanded', 'true');
				break;
			}

			if( closeOtherToggles == true ) {
				accordion.parentElement.querySelectorAll('.oxel_accordion__row--active').forEach( row => {
					if( row != accordion ) { 
						row.classList.remove('oxel_accordion__row--active');
						row.setAttribute('aria-expanded', 'false');
						row.nextElementSibling.classList.add('oxel_accordion__content__hidden');
					}
				});
			}
		})
	})

});

